"""Newton slope pair and non-integrality propagation."""
from fractions import Fraction
from typing import Tuple

def frobenius_slopes(k: int, s: Fraction) -> Tuple[Fraction, Fraction]:
    """Return (lowSlope, highSlope) = (s, (k-1) - s) for X^2 - a_p X + p^(k-1)."""
    return s, Fraction(k - 1) - s

def is_integral(q: Fraction) -> bool:
    return q.denominator == 1

def report(k: int, s: Fraction) -> None:
    low, high = frobenius_slopes(k, s)
    print(f"k={k}, v(a_p)={s}: low={low}, high={high}, "
          f"sum={low+high} (=k-1={k-1}), "
          f"both fractional={not is_integral(low) and not is_integral(high)}")

if __name__ == "__main__":
    for k, s in [(12, Fraction(1,2)), (50, Fraction(7,3)), (100, Fraction(1,5))]:
        report(k, s)

"""Even-weight balanced slope is always a genuine half-integer."""
from fractions import Fraction

def balanced_slope(k: int) -> Fraction:
    """The balanced Newton slope (k-1)/2."""
    return Fraction(k - 1, 2)

def is_half_integer(k: int) -> bool:
    q = balanced_slope(k)
    return q.denominator == 2  # never an integer for even k

if __name__ == "__main__":
    for k in [2, 4, 12, 100]:
        q = balanced_slope(k)
        print(f"k={k} (even): balanced slope={q}, 2*slope={q*2} (=k-1), "
              f"half-integer={is_half_integer(k)}")

"""Discriminant criterion: residual irreducibility over F_p."""
def discriminant(a: int, d: int) -> int:
    return a*a - 4*d

def is_square_mod_p(e: int, p: int) -> bool:
    e %= p
    return e == 0 or pow(e, (p-1)//2, p) == 1

def residual_irreducible(a: int, d: int, p: int) -> bool:
    """Irreducible iff a^2 - 4d is a non-square in F_p."""
    return not is_square_mod_p(discriminant(a, d), p)

if __name__ == "__main__":
    p = 7
    for a, d in [(1,1), (2,3), (0,1), (3,5)]:
        print(f"a={a}, d={d}: disc={discriminant(a,d)%p} mod {p}, "
              f"irreducible={residual_irreducible(a,d,p)}")

