function NEWTON_SLOPE_PAIR(k, s):
    low  <- s
    high <- (k - 1) - s
    breaks <- (2*s < k - 1)
    return (low, high, breaks)

function BUILD_CERTIFICATE(k, s):
    low  <- s;  high <- (k-1) - s
    if k is odd:            return INVALID('k not even')
    if not (2*s < k-1):     return INVALID('not sub-balanced')
    if s is an integer:     return INVALID('slope integral')
    ok <- (low+high == k-1) and (low != high)
           and (low fractional) and (high fractional)
    return CERTIFICATE(ok, low, high)

