from fractions import Fraction
from dataclasses import dataclass
from typing import Optional

@dataclass
class Certificate:
    valid: bool
    low: Fraction
    high: Fraction
    diagnostic: Optional[str]

def build_certificate(k: int, s: Fraction) -> Certificate:
    """
    Assemble the fractional-slope irreducibility certificate for weight k
    and slope s = v(a_p). Valid iff k is even, 2*s < k-1, and s is fractional;
    then both slopes are fractional, distinct, and sum to k-1.
    """
    low, high = s, Fraction(k - 1) - s
    if k % 2 != 0:
        return Certificate(False, low, high, "weight k is not even")
    if not (2 * s < Fraction(k - 1)):
        return Certificate(False, low, high, "not sub-balanced: 2*s >= k-1")
    if s.denominator == 1:
        return Certificate(False, low, high, "slope s is an integer")
    ok = (low + high == Fraction(k - 1) and low != high
          and low.denominator != 1 and high.denominator != 1)
    return Certificate(ok, low, high, None)
